-- Approved G food portions. Staging only; no migration or production entry is installed here.
create or replace function ml_private.p3g_food_original_allowed(s jsonb,c jsonb,target integer) returns boolean language sql stable set search_path=pg_catalog,ml_private as $$select c->>'countered'<>'true' and ml_private.stage4_on_board(s,target) and case when c->>'definition'='basic-038' then coalesce(c#>>'{stage4,counterEffective}','false')='true' else not(c->'cancelled' @> jsonb_build_array(target)) and ml_private.stage3_card_allowed(s,target,c->>'definition',c->'effect') and not(coalesce(c#>'{stage4,officeExempt}','[]') @> jsonb_build_array(target)) end$$;
create or replace function ml_private.p3g_food_thief(s jsonb,c jsonb,target integer) returns integer language sql stable set search_path=pg_catalog,ml_private as $$select (v#>>'{}')::int from jsonb_array_elements(s->'order') with ordinality q(v,n) where ml_private.p3g_enabled(s) and ml_private.p3g_food_original_allowed(s,c,target) and v<>c->'actor' and ml_private.stage4_on_board(s,(v#>>'{}')::int) and s#>>array['players',v#>>'{}','character']='character-021' and (s#>>array['players',v#>>'{}','ap'])::int>=2 and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',v,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) order by n limit 1$$;
create or replace function ml_private.p3g_food_portions(c jsonb,targets jsonb) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(ml_private.stage3_task('g-food-portion',jsonb_build_object('serial',c->'serial','target',v)) order by n),'[]') from jsonb_array_elements(targets) with ordinality q(v,n)$$;
create or replace function ml_private.p3g_food_apply(s jsonb,c jsonb,target integer,thief integer) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare effect jsonb:=c->'effect';definition text:=c->>'definition';amount integer;buff text;begin
 if thief is not null then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',thief,'kind','active')));end if;
 if not ml_private.stage4_on_board(s,target) or thief is not null and (not ml_private.stage3_card_allowed(s,target,definition,effect) or not ml_private.stage4_location_effect(s,target,definition)) then return s;end if;
 s:=ml_private.p3c_mark_food(s,jsonb_build_array(target));
 if definition='basic-048' then s:=ml_private.p3g_die(s,'油泼',(c->>'actor')::int);amount:=(s->>'_roll')::int;s:=s-'_roll';
  if amount=6 then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',c->'actor','category','attack')));s:=ml_private.stage3_prepend(s,s->'_triggers');return s-'_triggers';
  else return ml_private.heal(s,target,case when ml_private.p3f_uncapped(s,target) then 2 else (s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int end,true);end if;
 end if;
 amount:=case when definition='basic-046' then 2 when definition='basic-040' and s#>>array['players',target::text,'character']='character-040' then (s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int else 1 end;s:=ml_private.heal(s,target,amount,true);
 if definition='basic-045' then s:=jsonb_set(s,array['players',target::text,'shield'],to_jsonb((s#>>array['players',target::text,'shield'])::int+least(1,2-(s#>>array['players',target::text,'shield'])::int)));end if;
 if definition='basic-047' then s:=ml_private.draw(s,target,2);end if;
 buff:=case definition when 'basic-042' then 'tea' when 'basic-043' then 'dodge' when 'basic-044' then 'exerciseFree' else null end;
 if buff is not null then s:=jsonb_set(s,array['stage4',buff,target::text],'true');s:=jsonb_set(s,array['stage4','buffSources',target::text||':'||buff],effect);if buff='exerciseFree' then s:=jsonb_set(s,array['stage4','exerciseGuard',target::text],'true');end if;end if;return s;
end $$;
create or replace function ml_private.p3g_food_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare c jsonb:=s#>'{cardStack,stack,-1}';targets jsonb;target integer:=(t->>'target')::int;thief integer;definition text:=c->>'definition';begin
 if not ml_private.p3g_enabled(s) or c is null or t ? 'serial' and t->'serial'<>c->'serial' then return s||jsonb_build_object('_gFoodHandled',false);end if;
 if t->>'action'='effect' and c->'responseTo'='null'::jsonb and ml_private.version_catalog(s->>'version')#>>array['runtimeData','cards',definition,'type']='food' then s:=ml_private.stage3_record_combo(s,(c->>'actor')::int,definition);
  select coalesce(jsonb_agg(v order by n),'[]') into targets from jsonb_array_elements(s->'order') with ordinality q(v,n) where c->'targets' @> jsonb_build_array(v) and ml_private.p3g_food_original_allowed(s,c,(v#>>'{}')::int);
  s:=ml_private.stage3_prepend(s,ml_private.p3g_food_portions(c,targets)||jsonb_build_array(ml_private.stage3_task('g-food-finish',jsonb_build_object('serial',c->'serial')),ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));
 elsif t->>'action'='g-food-finish' then s:=ml_private.emit(s,'effect',(ml_private.version_catalog(s->>'version')#>>array['runtimeData','cards',definition,'name'])||'结算');
 elsif t->>'action'='g-food-portion' then if ml_private.p3g_food_original_allowed(s,c,target) then thief:=ml_private.p3g_food_thief(s,c,target);if thief is not null then s:=ml_private.select_choice(s,'g-food',thief,at,jsonb_build_object('deadline',at+30000,'source',target,'data',jsonb_build_object('serial',c->'serial','original',target)));else s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('g-food-apply',jsonb_build_object('serial',c->'serial','target',target,'data',jsonb_build_object('recipient',target)))));end if;end if;
 elsif t->>'action'='g-food-apply' then if ml_private.p3g_food_original_allowed(s,c,target) then s:=ml_private.p3g_food_apply(s,c,(t#>>'{data,recipient}')::int,(t#>>'{data,thief}')::int);end if;
 else return s||jsonb_build_object('_gFoodHandled',false);end if;return s||jsonb_build_object('_gFoodHandled',true);
end $$;
create or replace function ml_private.p3g_food_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare choice jsonb:=s->'choice';c jsonb:=s#>'{cardStack,stack,-1}';a integer:=(choice->>'actor')::int;original integer:=(choice#>>'{data,original}')::int;recipient integer:=original;data jsonb;begin
 if not ml_private.p3g_enabled(s) or choice->>'kind'<>'g-food' then return s||jsonb_build_object('_gFoodHandled',false);end if;perform ml_private.need(c is not null and c->'serial'=choice#>'{data,serial}','过境食物已失效');
 data:=jsonb_build_object('recipient',original);
 if not timeout and cmd->>'accept'='true' then perform ml_private.need(ml_private.p3g_food_thief(s,c,original)=a,'过境受益者、费用或资格已失效');s:=ml_private.p3d_pay(s,a,2);recipient:=a;data:=jsonb_build_object('recipient',a,'thief',a);s:=ml_private.emit(s,'skill','S'||(a+1)||' 过境支付2AP，取得S'||(original+1)||'的一份食物效果');end if;
 s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('g-food-apply',jsonb_build_object('serial',c->'serial','target',original,'data',data))));return s||jsonb_build_object('_gFoodHandled',true);
end $$;
